<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('SOLICITUD_CREAR');$in=json_input();$dep=(int)($in['departamento_id']??0);$sub=($in['subitem_id']??'')!==''?(int)$in['subitem_id']:null;$amount=money_value($in['monto']??0);$concept=trim((string)($in['concepto']??''));$benefUser=($in['otorgado_a_usuario_id']??'')!==''?(int)$in['otorgado_a_usuario_id']:null;$benefName=trim((string)($in['beneficiario_nombre']??''));$area=trim((string)($in['area_solicitante']??''));$year=(int)($in['ejercicio']??date('Y'));if($dep<=0||$amount<=0||$concept==='')json_response(['ok'=>false,'error'=>'Departamento, monto y concepto son obligatorios'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$allowed=visible_department_ids($db,$user);if(!user_is_global($user)&&!in_array($dep,$allowed,true)){$db->close();json_response(['ok'=>false,'error'=>'No puedes crear solicitudes para ese departamento'],403);}if($sub!==null){$st=$db->prepare("SELECT tipo,departamento_id,estatus FROM presupuesto_subitem WHERE subitem_id=? LIMIT 1");$st->bind_param('i',$sub);$st->execute();$subitem=$st->get_result()->fetch_assoc();$st->close();if(!$subitem||$subitem['estatus']!=='ACTIVO'||$subitem['tipo']!=='SALIDA'){$db->close();json_response(['ok'=>false,'error'=>'Las solicitudes solo pueden usar sub-items activos de salida'],409);}if($subitem['departamento_id']!==null&&(int)$subitem['departamento_id']!==$dep){$db->close();json_response(['ok'=>false,'error'=>'El sub-item seleccionado pertenece a otro departamento'],409);}}$balance=department_balance($db,$dep,$year);if($amount>$balance['disponible']){$db->close();json_response(['ok'=>false,'error'=>'El monto solicitado excede el presupuesto disponible'],409);}$folio=next_folio($db,'SOLICITUD',$year);$uid=(int)$user['user_id'];$date=date('Y-m-d');$st=$db->prepare("INSERT INTO presupuesto_solicitud(folio,ejercicio,departamento_id,subitem_id,fecha_solicitud,monto_solicitado,concepto,solicitado_por_usuario_id,otorgado_a_usuario_id,beneficiario_nombre,area_solicitante,estatus) VALUES(?,?,?,?,?,?,?,?,?,?,?,'PENDIENTE')");$st->bind_param('siiisdiisss',$folio,$year,$dep,$sub,$date,$amount,$concept,$uid,$benefUser,$benefName,$area);$st->execute();$id=(int)$st->insert_id;$st->close();audit_log($db,$uid,'SOLICITUD_CREAR','SOLICITUD',$id,'Solicitud '.$folio,null,$in);$db->close();json_response(['ok'=>true,'data'=>['solicitud_id'=>$id,'folio'=>$folio]]);
